      "inputSchema": {
        "type": "object",
        "properties": {
          "channels": {
            "type": "integer",
            "description": "Even channel count 2..32"
          },
          "name": {
            "type": "string",
            "description": "Song name"
          }
        },
        "additionalProperties": false
      }
    },
    {
      "name": "module_load",
      "description": "Load a module from disk",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          }
        },
        "required": [
          "path"
        ],
        "additionalProperties": false
      }
    },
